CB0 = CA0 * razao_molar
CE0 = 0.0
CW0 = 0.0
C0 = [CA0, CB0, CE0, CW0]


# Concentração experimental de CE em mol/L
ce_exp = (dados[:, 1]) * CA0

t_final = dados[-1, 0]
t_span = (0, t_final)
t_eval = np.arange(0, t_final, 1)  # até antes do último ponto

guess=[0.01, 1]
guess_ = [0.01,1,0.1]


ajustar_modelo(dados,C0,ce_exp, t_span,t_eval, guess)

